def solve(grid):
    """Count the number of islands in a binary grid.
    An island is a group of adjacent cells with value 1 connected vertically or horizontally.
    Args:
        grid (list[list[int]]): 2‑D list of 0s and 1s.
    Returns:
        int: Number of islands.
    """
    if not grid:
        return 0
    rows, cols = len(grid), len(grid[0])
    visited = [[False] * cols for _ in range(rows)]
    def dfs(r, c):
        stack = [(r, c)]
        while stack:
            i, j = stack.pop()
            if visited[i][j]:
                continue
            visited[i][j] = True
            # explore neighbors
            for di, dj in ((1,0), (-1,0), (0,1), (0,-1)):
                ni, nj = i + di, j + dj
                if 0 <= ni < rows and 0 <= nj < cols:
                    if not visited[ni][nj] and grid[ni][nj] == 1:
                        stack.append((ni, nj))
    islands = 0
    for i in range(rows):
        for j in range(cols):
            if grid[i][j] == 1 and not visited[i][j]:
                islands += 1
                dfs(i, j)
    return islands

