def solve(tokens):
    """Evaluate Reverse Polish Notation expression.
    tokens: list of string tokens, numbers or '+', '-', '*', '/'.
    Division truncates toward zero.
    Returns integer result.
    """
    stack = []
    for t in tokens:
        if t in {"+", "-", "*", "/"}:
            b = stack.pop()
            a = stack.pop()
            if t == '+':
                stack.append(a + b)
            elif t == '-':
                stack.append(a - b)
            elif t == '*':
                stack.append(a * b)
            else:  # '/'
                # Truncate toward zero
                stack.append(int(a / b))
        else:
            stack.append(int(t))
    return stack[0] if stack else 0

