    """Merge overlapping or touching intervals.
    Handles possible malformed interval entries gracefully.
    """
    # Filter out any entries that are not length-2 iterables
    cleaned = []
    for iv in intervals:
        try:
            if len(iv) == 2:
                start, end = iv[0], iv[1]
                # Ensure start <= end as per spec; if not, swap
                if start > end:
                    start, end = end, start
                cleaned.append([start, end])
        except Exception:
            # ignore non-iterable entries
            continue
    if not cleaned:
        return []
    # sort by start
    cleaned.sort(key=lambda x: x[0])
    merged = []
    cur_start, cur_end = cleaned[0]
    for start, end in cleaned[1:]:
        if start <= cur_end:  # overlap or touch
            cur_end = max(cur_end, end)
        else:
            merged.append([cur_start, cur_end])
            cur_start, cur_end = start, end
    merged.append([cur_start, cur_end])
