def solve(intervals):
    """Merge overlapping or touching intervals.
    Returns [] if any interval is malformed (not length‑2, non‑numeric, or start > end).
    """
    # Validate intervals
    valid = []
    for iv in intervals:
        try:
            if len(iv) != 2:
                return []
            start, end = iv[0], iv[1]
        except Exception:
            return []
        # Ensure numeric types
        if not (isinstance(start, (int, float)) and isinstance(end, (int, float))):
            return []
        # Enforce start <= end as per specification
        if start > end:
            return []
        valid.append([start, end])
    if not valid:
        return []
    # Sort by start
    valid.sort(key=lambda x: x[0])
    merged = []
    cur_start, cur_end = valid[0]
    for start, end in valid[1:]:
        if start <= cur_end:  # overlap or touch
            cur_end = max(cur_end, end)
        else:
            merged.append([cur_start, cur_end])
            cur_start, cur_end = start, end
    merged.append([cur_start, cur_end])
    return merged
}

