def solve(nums):
    """Return length of longest strictly increasing subsequence.
    Implements patience sorting with binary search (O(n log n)).
    """
    import bisect
    tails = []
    for x in nums:
        # Find index of first element >= x
        i = bisect.bisect_left(tails, x)
        if i == len(tails):
            tails.append(x)
        else:
            tails[i] = x
    return len(tails)

