def solve(grid):
    """Count islands in a grid of 0s and 1s.
    Handles ragged grids (rows of differing lengths) and empty inputs.
    Cells are connected vertically and horizontally.
    """
    if not grid:
        return 0
    n = len(grid)
    # Use a set for visited to handle ragged rows
    visited = set()
    def neighbors(i, j):
        for di, dj in ((1,0),(-1,0),(0,1),(0,-1)):
            ni, nj = i + di, j + dj
            if 0 <= ni < n and 0 <= nj < len(grid[ni]):
                yield ni, nj
    def dfs(i, j):
        stack = [(i, j)]
        while stack:
            x, y = stack.pop()
            if (x, y) in visited:
                continue
            visited.add((x, y))
            for nx, ny in neighbors(x, y):
                if (nx, ny) not in visited and grid[nx][ny] == 1:
                    stack.append((nx, ny))
    count = 0
    for i, row in enumerate(grid):
        for j, val in enumerate(row):
            if val == 1 and (i, j) not in visited:
                count += 1
                dfs(i, j)
    return count

