def solve(grid):
    """Count the number of islands in a 2D grid.
    An island is a group of cells with value 1 connected vertically or horizontally.
    The grid may be empty or have rows of varying lengths.
    """
    if not grid:
        return 0
    m = len(grid)
    # Use visited set to avoid index errors on ragged rows
    visited = set()
    def neighbors(i, j):
        for di, dj in ((-1, 0), (1, 0), (0, -1), (0, 1)):
            ni, nj = i + di, j + dj
            if 0 <= ni < m and 0 <= nj < len(grid[ni]):
                yield ni, nj
    def bfs(i, j):
        stack = [(i, j)]
        while stack:
            x, y = stack.pop()
            if (x, y) in visited:
                continue
            visited.add((x, y))
            if grid[x][y] != 1:
                continue
            for nx, ny in neighbors(x, y):
                if (nx, ny) not in visited and grid[nx][ny] == 1:
                    stack.append((nx, ny))
    count = 0
    for i, row in enumerate(grid):
        for j, val in enumerate(row):
            if (i, j) not in visited and val == 1:
                count += 1
                bfs(i, j)
    return count

