def solve(nums):
    """Return the length of the longest strictly increasing subsequence.
    Handles None or empty input by returning 0. Accepts any iterable of
    integers (list, tuple, etc.) without mutating it.
    """
    if not nums:
        return 0
    # Ensure we have a list to iterate multiple times safely
    seq = list(nums)
    import bisect
    tails = []
    for x in seq:
        # Only integers are valid; if a non-int appears, raise TypeError
        if not isinstance(x, int):
            raise TypeError('All elements must be integers')
        i = bisect.bisect_left(tails, x)
        if i == len(tails):
            tails.append(x)
        else:
            tails[i] = x
    return len(tails)

